-- See docs/architecture/authentication-authorization.md.

-- CreateEnum
CREATE TYPE "user_role" AS ENUM ('USER', 'ADMIN');

-- AlterEnum (PostgreSQL 18 allows several ADD VALUE statements in one migration). The new API
-- error codes 403 and 429 are also valid analytics error codes; they are placed after
-- UNAUTHORIZED, as in schema.prisma.
ALTER TYPE "analytics_error_code" ADD VALUE 'FORBIDDEN' AFTER 'UNAUTHORIZED';
ALTER TYPE "analytics_error_code" ADD VALUE 'TOO_MANY_REQUESTS' AFTER 'FORBIDDEN';

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "role" "user_role" NOT NULL DEFAULT 'USER';

