-- ---------------------------------------------------------------------------------------------
-- CHECK constraints (hand-written).
-- ---------------------------------------------------------------------------------------------

ALTER TABLE "otp_challenges"
    -- The same E.164 rule as users.phone_number.
    ADD CONSTRAINT "otp_challenges_phone_number_e164_check" CHECK ("phone_number" ~ '^\+[1-9][0-9]{7,14}$'),
    -- HMAC-SHA-256 as 64 lowercase hex characters: never a plaintext code.
    ADD CONSTRAINT "otp_challenges_code_hash_format_check" CHECK ("code_hash" ~ '^[0-9a-f]{64}$'),
    ADD CONSTRAINT "otp_challenges_max_attempts_range_check" CHECK ("max_attempts" BETWEEN 1 AND 20),
    ADD CONSTRAINT "otp_challenges_attempts_range_check" CHECK ("attempts" >= 0 AND "attempts" <= "max_attempts"),
    ADD CONSTRAINT "otp_challenges_expires_after_created_check" CHECK ("expires_at" > "created_at"),
    -- A challenge ends once: used, or replaced by a newer one.
    ADD CONSTRAINT "otp_challenges_single_outcome_check" CHECK ("consumed_at" IS NULL OR "superseded_at" IS NULL);

ALTER TABLE "auth_sessions"
    -- SHA-256 of the refresh token as 64 lowercase hex characters: never the token itself.
    ADD CONSTRAINT "auth_sessions_refresh_token_hash_format_check" CHECK ("refresh_token_hash" ~ '^[0-9a-f]{64}$'),
    ADD CONSTRAINT "auth_sessions_expires_after_created_check" CHECK ("expires_at" > "created_at"),
    -- A session replaced by rotation is always revoked.
    ADD CONSTRAINT "auth_sessions_replaced_is_revoked_check" CHECK ("replaced_by_session_id" IS NULL OR "revoked_at" IS NOT NULL);
